(1, 'Holding No - New 68, Old 80, Ward-12, Nawab Salimullah Road, Mission Para, Narayanganj', NULL, 'Ali Akbar Palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div dir=\"ltr\"><span style=\"background-color: transparent; font-size: 18px;\"><font color=\"#000000\" face=\"Montserrat, sans-serif\">Ali Akbar Palace</font></span><font color=\"#000000\" face=\"Montserrat, sans-serif\"><span style=\"font-size: 18px;\"> is BTA’s flagship luxury apartment development located in the prestigious Nawab Salimullah Road, Mission Para, Narayanganj. Designed with a focus on lifestyle, space, and sophistication, this 9-story building offers 48 premium apartments ranging from 3 bedrooms — each crafted with elegant finishes, modern fixtures, and panoramic views of the city. </span></font></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-06-29', NULL, NULL, '17513662385273.jpg', '17513581212686.jpg', '17513544403899.pdf', NULL, NULL, NULL, 1, 6, 8, 0, 1, NULL, NULL, NULL, NULL, 'Ali Akbar Palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ali Akbar Palace is BTA’s flagship luxury apartment development located in the prestigious Nawab Salimullah Road, Mission Para, Narayanganj.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ali-akbar-palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2025-06-29 01:52:32', '2025-07-02 03:58:25'),
(2, 'House # 36/1, Ward # 15, Bangshal Road, Sutarpara, Nimtola, Nitaiganj, Narayanganj', NULL, 'BTA Mostafa Palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div dir=\"ltr\"><p data-start=\"81\" data-end=\"689\"><strong data-start=\"81\" data-end=\"99\">Mostafa Palace</strong> is a signature residential project by BTA, setting a new benchmark for upscale urban living in the heart of <strong data-start=\"208\" data-end=\"225\">Narayanganj</strong>. This elegant 10-story development features <strong data-start=\"270\" data-end=\"297\">32 exclusive apartments</strong> thoughtfully designed to blend luxury, comfort, and modern aesthetics. Each unit, ranging from <strong data-start=\"393\" data-end=\"412\">3 bedrooms</strong>, is enriched with high-end finishes, smart layouts, and spacious balconies offering serene views of the surrounding skyline. Mostafa Palace combines contemporary architecture with timeless appeal — making it an ideal choice for families seeking a refined and secure lifestyle.</p></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-06-29', NULL, NULL, '17513517279827.jpg', NULL, '17513613354621.pdf', NULL, NULL, NULL, 1, 11, 8, 0, 2, NULL, NULL, NULL, NULL, 'Mostafa palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Mostafa Palace is a signature residential project by BTA, setting a new benchmark for upscale urban living in the heart of Narayanganj.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mostafa-palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2025-06-29 01:55:18', '2025-07-02 03:58:58'),
(3, NULL, NULL, 'Royal Palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div dir=\"ltr\"><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-06-29', NULL, NULL, '17513521708583.jpg', NULL, NULL, NULL, NULL, NULL, 1, 7, 8, 0, 3, NULL, NULL, NULL, NULL, 'Royal Palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Green Heights is BTA’s flagship luxury apartment development located in the prestigious Bashundhara Residential Area of Dhaka', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'royal-palace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2025-06-29 03:18:49', '2025-07-01 09:50:54'),
